        "النقدي والفيزا يحتاجان وردية مناسبة مفتوحة. راجع المبلغ المستحق وأي رصيد سابق أو زيادة للمريض.",
        "مش محتاج تعمل ريفريش بعد فتح الوردية: لما تفتح «تسجيل تحصيل» خانة «وردية الكاش أو الفيزا» بتتحدّث لوحدها وبتختار ورديتك المفتوحة. لو مفيش وردية مفتوحة باسمك بيظهر «افتح ورديتك الأول» وزرار «افتح ورديتي».",
        "راجع رقم إيصال التحصيل والرصيد بعد الحفظ؛ إعادة طباعة إيصال لا تعني تسجيل دفعة ثانية.",
        "كل تحصيل في الاستقبال بياخد رقم إيصال متسلسل من الداشبورد لوحده (زي RC-2026-000123) — بيظهر في جدول التحصيلات وفي ملف المريض، ومش محتاج تكتبه.",
        "الفيزا وإنستا باي والتحويل البنكي والمحفظة: اكتب رقم العملية من إيصال الماكينة أو رسالة التحويل، وارفع صورة إيصال الماكينة أو سكرين شوت التحويل في خانة «صورة إيصال الماكينة أو التحويل». الصورة إجبارية، ومن غيرها الحفظ بيترفض. الصورة الواحدة بتتحسب لدفعة واحدة بس، ولو التحصيل بطريقتين ارفع صورة لكل جزء مش نقدي.",
        "فاتورة المريض: زرار «طباعة فاتورة الزيارة» (في جدول الفواتير أو في ملف المريض) بيطلع فاتورة واحدة لكل الزيارة حتى لو فيها كذا خدمة، برقم متسلسل (زي INV-2026-000045) على ورق المركز A4: الخدمات والخصم والصافي، وكل دفعة برقم إيصالها ورقم العملية، والمدفوع والمتبقي، وأماكن توقيع الموظف والمريض وختم المركز. الرقم بيتحدد أول مرة تطبع، ولو طبعت تاني بيطلع نفس الرقم.",
        "فاتورة المطالبة لشركات التأمين والتعاقدات: من «طباعة فاتورة مطالبة» اختار الزيارة واكتب الجهة ورقم العضوية ورقم الموافقة والنسب — بتطلع بنفس رقم فاتورة الزيارة، وفيها حصة المريض بإيصالاتها والمبلغ المطالَب بيه من الجهة ونسبة التغطية. ارفق معاها صورة الموافقة وصورة إيصال حصة المريض.",
        "كله مربوط ببعضه: الفاتورة → استحقاق الطبيب في حسابه → «صرف الحساب»، ورقم الإيصال هو اللي بتراجع بيه أي دفعة.",
        "شكل الطباعة: أي فاتورة أو إيصال أو مطالبة أو إيصال صرف بيطلع من الداشبورد بيتطبع على ورق المركز الرسمي A4 بنفس الشكل: اسم المستند ورقمه فوق، بيانات المريض أو الجهة في شريط رمادي، الجداول بعناوين زرقا، المبلغ بالأرقام وبالحروف، وأماكن التوقيع والختم. مفيش اسم مكتوب في العنوان، اللوجو اللي على الورق كفاية. زرار «عرض الإيصال» ← «طباعة» بيطلع إيصال سداد برقم الإيصال المتسلسل، و«عرض البيان» ← «طباعة» بيطلع بيان الخدمة والمستلزمات بنفس الشكل، والفاتورة الكاملة للزيارة من «طباعة فاتورة الزيارة». المطالبات الطويلة بيتكرر فيها ورق المركز وعناوين الجدول في كل صفحة.",
        "بيانات الطبيب: فاتورة الزيارة وفاتورة المطالبة فيهم عمود «الطبيب / التخصص» — اسم الطبيب اللي عمل الخدمة وتحته تخصصه، وفوق «الطبيب» و«التخصص» (لو أكتر من طبيب بيكتب «أكثر من طبيب»). جدول الفواتير على الشاشة فيه نفس العمود، وإيصال السداد وبيان الخدمة فيهم «الطبيب» و«التخصص» فوق.",
        "الأسهل للاستقبال: على كارت المريض اللي «حضر» في المواعيد دوس «تحصيل». لو الخدمة لسه ما اتنفذتش بيسألك الأول (لأن الفاتورة بتطلع بعد التنفيذ، وهيتسجل إن الخدمة اتنفذت باسمك)، وبعدين بيفتح «تسجيل تحصيل» على فاتورة الزيارة. لو الخدمة محتاجة قراءة جهاز بتظهر رسالة وتتفتح تفاصيل الزيارة تكمّل منها."
