        "«فحص» مش بيمسح حاجة. بيوريك إيه اللي هيتمسح لو السجل اتحذف، ولو مرفوض بيقولك مرتبط بإيه.",
        "لو السجل سليم، اكتب السبب وكلمة «تجريبي» واضغط «علّم كتجريبي». السجل بينزل في قايمة المعلَّمة، وتقدر تلغي العلامة بسبب.",
        "من قايمة المعلَّمة اضغط «حذف نهائي»، واكتب السبب وكلمة «حذف». مفيش رجوع من الشاشة، والنسخة الكاملة بتفضل في الأرشيف مع مين حذف وإمتى وليه.",
        "الفاتورة بتترفض لو عليها دفع أو استرداد أو تأمين أو صرف أتعاب أو مخزون. والصنف بيترفض لو عليه حركة مخزون.",
        "مقدم الحجز بيتحذف بس لو ما اتستخدمش خالص: مش متخصم على فاتورة، ومفيش عليه طلب استرداد، ومش مربوط بحجز مريض.",
        "ولازم فلوس المقدم تكون لسه في نفس الخزينة: الوردية مفتوحة وما اتجردتش، ومفيش تسليم نقدية منها، ومفيش وردية تانية اشتغلت بعدها على نفس الخزينة.",
        "مقدم الشبكة أو التحويل أو المحفظة اللي اتسجل في الدفاتر بيترفض هنا، ومحتاج تسوية من الحسابات.",
        "مع المقدم بيتمسح قيد الاستلام بتاعه. ولو المقدم اتسجل قبل ربط الخزينة بحسابها، بيتمسح معاه قيد ربط العهدة اللي نقل نفس المبلغ بس، علشان حساب الخزينة يرجع صفر. لو قيد الربط فيه مبالغ تانية، الحذف بيترفض.",
