        "قائمة الدخل للفرع: الإيرادات وتكلفة الخدمات والمصروفات الإدارية وصافي الربح قصاد الفترة اللي قبلها بنفس الطول، من دفتر الحسابات العام. لو اخترت فرع، القيود العامة اللي مش متوزعة على فرع بتظهر في ملاحظة لوحدها.",
