        "استهلاك الأدوية: الصيدلية مخزن زي أي مخزن. الدوا اللي داخل في الخدمة بيظهر كتكلفة على المركز، واللي المريض دفع تمنه لوحده بيظهر كبيع وتكلفته وربحه.",
