        "التارجت مقابل الفعلي: التارجت الشهري بيتحط للفرع أو لشخص أو لدور كامل (مدير الفرع، السوشيال ميديا، الكول سنتر، الاستقبال) أو لحملة إعلانية (تكلفة الحجز). المدير العام والمدير المالي واللي المالك يضيفهم بيقترحوا من «التقارير ← إدارة التارجت الشهري»، والمالك بس اللي بيوافق؛ التارجت مش بيدخل التقرير غير بعد الموافقة. التقرير بيحسب الفعلي ونسبة التحقيق، والمؤشرات اللي الأقل فيها أحسن (زي تكلفة الليد ووقت الرد) بتتحسب بالعكس.",
        "هامش ربح كل خدمة: لكل خدمة الإيراد، وبعد التخفيض التعاقدي وحصة الدكتور المنفذ ونسبة الإحالة وتكلفة المستلزمات اللي اتصرفت فيها يطلع الهامش ونسبته وهامش المرة. المصروفات العامة (إيجار ومرتبات) مش متوزعة على الخدمات، شوفها في قائمة الدخل. التقرير للإدارة والمدير المالي بس.",
        "تشغيل وعائد كل جهاز: لكل جهاز مرات الاستخدام في اليوم والساعات وقراءة العداد (طلقات أو ساعات)، والإيراد اللي جابه بعد التكاليف المباشرة. لو الجهاز مش مربوط بسجل الأصول، التقرير بيعرض المساهمة بس من غير العائد على تكلفة الجهاز.",
